[
    SysEntryPointAttribute(false)
]
public void execute(AVAExecuteAsynchronousContract contract)
{
    AVAExecuteAsynchronous  executeAsynchronous;

    executeAsynchronous = AVAExecuteAsynchronous::construct(contract.parmExecuteAsynchronouseType());
    executeAsynchronous.parmExecuteAsynchronousContract(contract);
    executeAsynchronous.execute();
}
